class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    """Resolve ``ansible.module_utils`` imports, preferring local files."""

    _module_utils_prefix_length = 2
    _redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        if mu_paths is None:
            mu_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
            mu_paths.append(_MODULE_UTILS_PATH)
        self.mu_paths = list(mu_paths)
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)
        self._resolve()

    def _try_local(self, candidate):
        relative_parts = candidate[2:]
        if not relative_parts:
            return False

        # six creates synthetic ``moves`` modules in sys.modules. Shipping
        # those generated modules separately can give imports conflicting identities.
        if relative_parts[0] in ('six', '_six'):
            relative_parts = ('six',)
            candidate = ('ansible', 'module_utils', 'six')

        paths = [os.path.join(path, *relative_parts[:-1]) for path in self.mu_paths]
        try:
            info = ModuleInfo(relative_parts[-1], paths)
        except ImportError:
            return False

        if not info.pkg_dir and not info.py_src:
            return False

        self._set_result(candidate, info.get_source(), info.pkg_dir, info.path)
        return True

    def _try_redirect(self, candidate):
        relative_name = '.'.join(candidate[2:])
        redirect_parts = _module_utils_route('ansible.builtin', relative_name, '.'.join(candidate))
        if not redirect_parts:
            return False
        redirect = self._redirect_source(candidate, redirect_parts)
        self._set_result(candidate, redirect.source, redirect.is_package, redirect.path, redirected=True)
        return True

    def package_init_source(self, package_parts):
        relative_parts = package_parts[2:]
        for path in self.mu_paths:
            package_path = os.path.join(path, *relative_parts)
            if os.path.isdir(package_path):
                init_path = os.path.join(package_path, '__init__.py')
                if os.path.isfile(init_path):
                    return _slurp(init_path), init_path
                return b'', init_path
        return b'', '/'.join(package_parts) + '/__init__.py'


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    """Resolve collection ``module_utils`` imports, preferring redirects."""

    _module_utils_prefix_length = 5
    _redirect_first = True

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        if (len(fq_name_parts) < 5 or tuple(fq_name_parts[:1]) != ('ansible_collections',) or
                tuple(fq_name_parts[3:5]) != ('plugins', 'module_utils')):
            raise ValueError('must search for something beneath a collection module_utils, not {0}'.format(
                '.'.join(fq_name_parts)))
        self.collection_name = '.'.join(fq_name_parts[1:3])
        self.collection_package = 'ansible_collections.{0}'.format(self.collection_name)
        try:
            self.collection_meta = _get_collection_metadata(self.collection_name)
        except ValueError as e:
            message = to_native(e)
            if 'unable to locate collection' in message:
                raise AnsibleError(message)
            raise
        super(CollectionModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)
        self._resolve()

    def _resource_data(self, resource_path):
        try:
            return pkgutil.get_data(self.collection_package, to_native(resource_path))
        except (IOError, OSError):
            return None

    def _try_local(self, candidate):
        relative_parts = candidate[5:]
        resource_base = os.path.join('plugins', 'module_utils', *relative_parts)
        package_path = os.path.join(resource_base, '__init__.py')
        source = self._resource_data(package_path)
        if source is not None:
            self._set_result(candidate, source, True,
                             os.path.join(self.collection_package.replace('.', '/'), package_path))
            return True

        source = self._resource_data(resource_base + '.py')
        if source is None:
            if not relative_parts:
                self._set_result(candidate, b'', True,
                                 os.path.join(self.collection_package.replace('.', '/'), package_path))
                return True
            return False
        self._set_result(candidate, source, False,
                         os.path.join(self.collection_package.replace('.', '/'), resource_base + '.py'))
        return True

    def _try_redirect(self, candidate):
        relative_name = '.'.join(candidate[5:])
        route = self.collection_meta.get('plugin_routing', {}).get('module_utils', {}).get(relative_name, {})
        if not route:
            return False
        redirect_parts = _module_utils_route(self.collection_name, relative_name, '.'.join(candidate))
        if not redirect_parts:
            return False
        redirect = self._redirect_source(candidate, redirect_parts)
        self._set_result(candidate, redirect.source, redirect.is_package, redirect.path, redirected=True)
        return True

    def package_init_source(self, package_parts):
        if tuple(package_parts[:3]) != tuple(self.fq_name_parts[:3]):
            return b'', '/'.join(package_parts) + '/__init__.py'
        relative_parts = package_parts[3:]
        if relative_parts:
            resource_path = os.path.join(*relative_parts, '__init__.py')
        else:
            resource_path = '__init__.py'
        source = self._resource_data(resource_path)
        output_path = os.path.join(self.collection_package.replace('.', '/'), resource_path)
        return (source if source is not None else b''), output_path


